<?php
namespace App\Http\Controllers\Accounting;use App\Http\Controllers\Controller;use App\Models\{BankReconciliation,FinancialAccount,JournalLine};use Illuminate\Http\Request;
class ReconciliationController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('accounting.reconciliations',['accounts'=>FinancialAccount::with('ledgerAccount')->where('property_id',$p)->where('active',1)->get(),'rows'=>BankReconciliation::with('financialAccount')->where('property_id',$p)->latest()->paginate(20)]);}public function store(Request $r){$d=$r->validate(['financial_account_id'=>'required|integer','statement_date'=>'required|date','statement_balance'=>'required|numeric','notes'=>'nullable']);$p=auth()->user()->property_id;$fa=FinancialAccount::where('property_id',$p)->findOrFail($d['financial_account_id']);$book=0;if($fa->account_id){$row=JournalLine::join('journal_entries','journal_entries.id','=','journal_lines.journal_entry_id')->where('journal_entries.property_id',$p)->where('journal_entries.status','posted')->where('journal_lines.account_id',$fa->account_id)->whereDate('journal_entries.entry_date','<=',$d['statement_date'])->selectRaw('COALESCE(SUM(debit-credit),0) b')->first();$book=(float)$row->b;}$diff=(float)$d['statement_balance']-$book;BankReconciliation::create(['property_id'=>$p,'financial_account_id'=>$fa->id,'statement_date'=>$d['statement_date'],'statement_balance'=>$d['statement_balance'],'book_balance'=>$book,'difference'=>$diff,'status'=>abs($diff)<.01?'reconciled':'draft','notes'=>$d['notes']??null,'reconciled_by'=>abs($diff)<.01?auth()->id():null,'reconciled_at'=>abs($diff)<.01?now():null]);return back()->with('success','Reconciliation saved.');}}
